style.css:
@-moz-document domain("onenote.com") {
body, #app-root {
    background: linear-gradient(135deg, #ffc6ff, #ffd6a5, #fdffb6, #caffbf, #9bf6ff, #bdb2ff);
    background-size: 1200% 1200%;
    animation: pastelRainbowBG 30s ease infinite;
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif !important;
    color: #222 !important;
  }

  @keyframes pastelRainbowBG {
    0% {background-position:0% 50%;}
    50% {background-position:100% 50%;}
    100% {background-position:0% 50%;}
  }

  [data-automation-id="sidebar"] {
    background: #bdb2ff !important;
    border-right: 2px solid #ffc6ff !important;
    color: #222 !important;
  }

  [role="banner"] {
    background: #9bf6ff !important;
    border-bottom: 2px solid #caffbf !important;
    color: #222 !important;
  }

  [data-automation-id="page-content"] {
    background: #fdffb6 !important;
    border-radius: 12px !important;
    padding: 12px !important;
    box-shadow: 0 0 15px #ffc6ff88 !important;
    color: #222 !important;
  }

  button, .ms-Button {
    background: #caffbf !important;
    border: 1.5px solid #bdb2ff !important;
    color: #222 !important;
    font-weight: 600 !important;
    border-radius: 8px !important;
    transition: background 0.3s ease;
  }

  button:hover, .ms-Button:hover {
    background: #ffc6ff !important;
    border-color: #ffadad !important;
    color: #222 !important;
  }

  input, textarea {
    background: #fff3e8 !important;
    border: 1.5px solid #9bf6ff !important;
    border-radius: 6px !important;
    color: #222 !important;
    font-weight: 500 !important;
  }

  ::-webkit-scrollbar {
    width: 12px;
  }

  ::-webkit-scrollbar-track {
    background: #fdffb6;
    border-radius: 10px;
  }

  ::-webkit-scrollbar-thumb {
    background: #bdb2ff;
    border-radius: 10px;
  }

  a {
    color: #bdb2ff !important;
    font-weight: 600 !important;
  }

  a:hover {
    color: #ffc6ff !important;
    text-decoration: underline !important;
  }
}
